/**
 * Employee Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change is a type error here instead of a silent runtime
 * mismatch. Request payloads, query params and UI value objects stay local and
 * are marked as such.
 */

import type { components } from "@/lib/types/api.generated"
import type { SearchableQuery } from "./common"

type Schemas = components["schemas"]

/** Wire vocabulary (Prisma enums as the API sends them). */
export type EmployeeGender = Schemas["EmployeeGender"]
export type EmploymentType = Schemas["EmploymentType"]
export type OnboardingStatus = Schemas["OnboardingStatus"]
export type DeliveryType = Schemas["DeliveryType"]

/* ─── Entities (derived from OpenAPI) ─── */

/** The wire row for GET list/detail (internal name; see `Employee`). */
export type EmployeeWire = Schemas["EmployeeResponseDto"]
/** The wire row for GET :id (adds `exceptions`). */
export type EmployeeDetailWire = Schemas["EmployeeDetailResponseDto"]
type EmployeeServiceWire = Schemas["EmployeeAssignedServiceDto"]
type ServiceWire = Schemas["ServiceRecordDto"]
type AvailabilityWindowWire = Schemas["EmployeeAvailabilityWindowRecordDto"]
type BreakWire = Schemas["EmployeeBreakRecordDto"]

/**
 * Dashboard-facing employee row.
 *
 * The API sends one display `name` plus optional `nameAr`/`nameEn`; it has no
 * linked user row and no name parts. `mapEmployee` (`lib/api/employees.ts`)
 * splits the display name once and attaches the synthetic `user` projection,
 * which is the only reason that field exists.
 *
 * Documented deviations from the wire, applied in `mapEmployee` and asserted by
 * `apps/dashboard/test/unit/lib/employee-type-contract.spec.ts`:
 *  - `user`: synthetic projection of `name`/`email`/`phone`; no endpoint sends it.
 *  - `specialty`: the wire allows null (legacy rows); the dashboard has always
 *    normalised it to "" so list/detail cells render blank instead of "—".
 *
 * Dropped from the old hand-written entity because the employee endpoints never
 * send them: `_count` (`mapEmployeeRow` emits `bookingCount`/`ratingCount`
 * directly), `rating`/`reviewCount` (only the public employee endpoints use
 * those names), and `priceClinic`/`pricePhone`/`priceVideo` (there is no legacy
 * per-type pricing column on `EmployeeService`).
 */
export type Employee = Omit<EmployeeWire, "specialty"> & {
  specialty: string
  user: EmployeeUser
}

/** Synthetic name/contact projection built by `mapEmployee`; not a wire shape. */
export interface EmployeeUser {
  id: string
  firstName: string
  lastName: string
  email: string
  phone: string | null
}

/** POST / PATCH /onboarding response: the raw employee row with its links. */
export type EmployeeWrite = Schemas["EmployeeWriteResponseDto"]

/** GET /dashboard/people/employees/:id — the list projection plus exceptions. */
export type EmployeeDetail = Omit<EmployeeDetailWire, "specialty"> & {
  specialty: string
  user: EmployeeUser
}

/* Compile-time guard: every field the API sends exists on the dashboard type. */
type MissingFromEmployee = Exclude<keyof EmployeeDetailWire, keyof EmployeeDetail>
const _employeeCoversWireShape: MissingFromEmployee extends never ? true : MissingFromEmployee = true
void _employeeCoversWireShape

/** A weekly availability window as the schedule editor consumes it. */
export type AvailabilitySlot = Pick<
  AvailabilityWindowWire,
  "dayOfWeek" | "startTime" | "endTime" | "isActive"
>

/** A stored break window (the API always returns an `id`). */
export type BreakSlot = Pick<BreakWire, "id" | "dayOfWeek" | "startTime" | "endTime">

/** A date-range time-off record; vacations are availability exceptions. */
export type Vacation = Schemas["EmployeeAvailabilityExceptionRecordDto"]

/** An available booking slot (`startTime`/`endTime` are HH:MM). */
export type TimeSlot = Schemas["EmployeeSlotDto"]

/** An employee-service assignment with its embedded service row. */
export type EmployeeService = EmployeeServiceWire

/** The service row embedded in an `EmployeeService`. */
export type ServiceRecord = ServiceWire

/** A bare employee-service link (assign / update responses, no service row). */
export type EmployeeServiceLink = Schemas["EmployeeServiceRecordDto"]

/** A bookable type with its effective duration options. */
export type EmployeeServiceType = Schemas["EmployeeServiceTypeDto"]

/** One duration option inside `EmployeeServiceType`. */
export type EmployeeServiceDurationOption = Schemas["EmployeeServiceTypeDurationOptionDto"]

/** A stored per-option price/duration override. */
export type EmployeeServiceOption = Schemas["EmployeeServiceOptionRecordDto"]

/** One delivery-type group returned when durations are saved. */
export type EmployeeEffectiveDurationGroup = Schemas["EmployeeEffectiveDurationGroupDto"]

/** Employee counters (GET /dashboard/people/employees/stats). */
export type EmployeeStats = Schemas["EmployeeStatsResponseDto"]

/* ─── Query ─── */

export type EmployeeSortField = "name" | "experience" | "isActive" | "createdAt"

export interface EmployeeListQuery extends SearchableQuery {
  minRating?: number
  isActive?: boolean
  sortBy?: EmployeeSortField
  sortOrder?: "asc" | "desc"
}

/* ─── Request payloads (local, not wire responses) ─── */

export interface CreateEmployeePayload {
  userId: string
  specialty: string
  specialtyAr?: string
  bio?: string
  bioAr?: string
  experience?: number
  education?: string
  educationAr?: string
  avatarUrl?: string | null
}

export interface UpdateEmployeePayload {
  title?: string | null
  nameAr?: string
  nameEn?: string
  email?: string
  phone?: string | null
  gender?: EmployeeGender
  employmentType?: EmploymentType
  specialty?: string | null
  specialtyAr?: string | null
  bio?: string | null
  bioAr?: string | null
  experience?: number
  education?: string | null
  educationAr?: string | null
  isActive?: boolean
  avatarUrl?: string | null
  slug?: string | null
  isPublic?: boolean
  publicBioAr?: string | null
  publicBioEn?: string | null
  publicImageUrl?: string | null
}

export interface SetAvailabilityPayload {
  schedule: AvailabilitySlot[]
}

export interface CreateVacationPayload {
  startDate: string
  endDate: string
  reason?: string
}

export interface SetBreaksPayload {
  breaks: Omit<BreakSlot, "id">[]
}

export interface AssignServicePayload {
  serviceId: string
}

export interface UpdateServicePayload {
  isActive?: boolean
  bufferMinutes?: number
}

/** Form-side per-delivery-type price/duration config (SAR, not halalas). */
export interface EmployeeTypeConfigPayload {
  deliveryType: string
  price?: number | null
  duration?: number | null
  useCustomOptions?: boolean
  isActive?: boolean
  durationOptions?: {
    id?: string
    label: string
    labelAr?: string
    durationMinutes: number
    price: number
    isDefault?: boolean
    sortOrder?: number
  }[]
}

export interface SetEmployeeServiceOptionsPayload {
  options: {
    durationOptionId: string
    priceOverride?: number | null
    durationOverride?: number | null
    deliveryType?: "IN_PERSON" | "ONLINE"
    isActive?: boolean
  }[]
}

export interface OnboardEmployeePayload {
  title?: string
  nameEn: string
  nameAr: string
  email: string
  phone?: string
  gender?: EmployeeGender
  employmentType?: EmploymentType
  specialty: string
  specialtyAr?: string
  bio?: string
  bioAr?: string
  experience?: number
  education?: string
  educationAr?: string
  avatarUrl?: string | null
  isActive?: boolean
  isPublic?: boolean
}

/**
 * POST /employees/onboarding. Unlike the read endpoints, create/update/onboard
 * return the raw Prisma employee row: no rating/booking counters, no
 * `branchIds`/`serviceIds` arrays, and `branches`/`services` link rows instead.
 * The dashboard only consumes `employee.id`, so the wire shape is used as-is.
 */
export type OnboardEmployeeResponse = Schemas["EmployeeOnboardResponseDto"]
